def insertion_point(xs, x):
    """Return the leftmost index at which x could be inserted into sorted
    list xs so that xs stays sorted (same contract as bisect.bisect_left).
    """
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo
